import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion"

type FaqSectionProps = {
  eyebrow: string
  heading: string
  items: Array<{ question: string; answer: string }>
}

/** Objection queue as an accordion — ordered by what buyers actually worry about. */
export function FaqSection({ eyebrow, heading, items }: FaqSectionProps) {
  return (
    <section className="mx-auto w-full max-w-3xl px-6 py-20">
      <p className="mb-2 text-center text-xs font-medium uppercase tracking-widest text-muted-foreground">{eyebrow}</p>
      <h2 className="mb-8 break-keep text-center text-2xl font-semibold tracking-tight text-foreground">{heading}</h2>
      <Accordion collapsible type="single">
        {items.map((item) => (
          <AccordionItem key={item.question} value={item.question}>
            <AccordionTrigger className="text-left text-sm font-medium">{item.question}</AccordionTrigger>
            <AccordionContent className="text-sm leading-relaxed text-muted-foreground">{item.answer}</AccordionContent>
          </AccordionItem>
        ))}
      </Accordion>
    </section>
  )
}

type FooterColumn = {
  heading: string
  links: string[]
}

type FooterSectionProps = {
  product: string
  tagline: string
  columns: FooterColumn[]
  legal: string
}

/** Closing footer: product identity left, link columns right, legal line under a divider. */
export function FooterSection({ product, tagline, columns, legal }: FooterSectionProps) {
  return (
    <footer className="border-t">
      <div className="mx-auto grid w-full max-w-5xl gap-10 px-6 py-14 md:grid-cols-[2fr_repeat(3,1fr)]">
        <div>
          <p className="text-sm font-semibold text-foreground">{product}</p>
          <p className="mt-2 max-w-xs text-sm leading-relaxed text-muted-foreground">{tagline}</p>
        </div>
        {columns.map((column) => (
          <nav aria-label={column.heading} key={column.heading}>
            <p className="mb-3 text-xs font-medium uppercase tracking-widest text-muted-foreground">{column.heading}</p>
            <ul className="space-y-2">
              {column.links.map((link) => (
                <li key={link}>
                  <a className="text-sm text-foreground/80 transition-colors hover:text-foreground" href="#">
                    {link}
                  </a>
                </li>
              ))}
            </ul>
          </nav>
        ))}
      </div>
      <div className="border-t">
        <p className="mx-auto w-full max-w-5xl px-6 py-6 text-xs text-muted-foreground">{legal}</p>
      </div>
    </footer>
  )
}

import { Button } from "@/components/ui/button"
import { FloatingBarsHero } from "@/components/floating-bars-hero"

type HeroSectionProps = {
  title: string
  description: string
  primaryCta: string
  secondaryCta: string
}

/** Opening screen: floating-bars hero with the block's two-action CTA slot. */
export function HeroSection({ title, description, primaryCta, secondaryCta }: HeroSectionProps) {
  return (
    <FloatingBarsHero
      title={title}
      description={description}
      actions={
        <div className="flex flex-wrap items-center justify-center gap-3">
          <Button size="lg">{primaryCta}</Button>
          <Button size="lg" variant="outline">
            {secondaryCta}
          </Button>
        </div>
      }
    />
  )
}

